 if(replyBusy){setStatus(s.replyPhase==='emitting'?t('Devolviendo confirmación por luz'):t('Mensaje recibido · preparando confirmación'),s.replyPhase==='emitting'?t('Mantén los móviles orientados.'):t('El aviso de vuelta empieza en 8 segundos.'));return;}if(ackWait){setStatus(liveReceiver.decoder.phase==='data'?t('Leyendo confirmación…'):t('Buscando el aviso de vuelta'),t('Toca la luz del otro móvil para fijar el punto.'));return;}if(s.mode!=='listen'||s.analyzing)return;
