 if(!s.stream){setStatus(t('Cámara apagada'),t('Activa la cámara para recibir la luz.'));return;}
 if(s.paused){setStatus(t('Escucha pausada'),t('Pulsa «Continuar» cuando el emisor esté preparado.'));return;}
 if(s.method==='video'){setStatus(t('Listo para grabar'),t('Empieza a grabar antes de que el otro móvil emita.'));return;}
 const d=liveReceiver.decoder;
 if(s.messageAt&&performance.now()-s.messageAt<15000){setStatus(t('Mensaje recibido'),t('Puedes escucharlo o tocar el texto para abrirlo.'));return;}
 if(d.phase==='data'){setStatus(t('Leyendo mensaje…'),t('Mantén los dos dispositivos quietos hasta que aparezca el texto.'));return;}
 if(performance.now()-s.errorAt<4500){setStatus(t('No se completó el mensaje'),t('Fija bien el punto y reduce la velocidad del emisor.'));return;}
